	if err != nil {
		t.Fatal(err)
	}
	if !re.MatchString(id) {

			t.Fatalf("invalid uuid %s", id)
		}
		if seen[id] {
			t.Fatal("duplicate uuid")
		}
		seen[id] = true
	}
}

